<script setup lang="ts">
import { computed, onMounted, ref, watch, type Component } from 'vue'
import { useRouter } from 'vue-router'
import { adoptionApi } from '@/lib/api'
import { AdoptionStatusMap, type AdoptionStatus, type MyAdoptionItem, type MyAdoptionQueryParams } from '@/types'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { ArrowLeft, Ban, CheckCircle2, ClipboardCheck, Clock3, HeartHandshake, MessageSquareText, XCircle } from 'lucide-vue-next'

const router = useRouter()
const pageSize = 10
const adoptionList = ref<MyAdoptionItem[]>([])
const currentPage = ref(1)
const totalPages = ref(1)
const total = ref(0)
const selectedStatus = ref<AdoptionStatus | ''>('')
const loading = ref(false)
const loadError = ref('')
let latestRequestId = 0

const adoptionStatusOrder: AdoptionStatus[] = ['PENDING', 'INTERVIEW', 'APPROVED', 'REJECTED', 'COMPLETED', 'CANCELLED']
const statusTabs: Array<{ label: string; value: AdoptionStatus | '' }> = [
  { label: '全部申请', value: '' },
  ...adoptionStatusOrder.map((status) => ({ label: AdoptionStatusMap[status], value: status }))
]
const statusConfig: Record<AdoptionStatus, { label: string; class: string; icon: Component }> = {
  PENDING: { label: AdoptionStatusMap.PENDING, class: 'border-[#FACC15] bg-[#FFF8DE] text-[#8A5A00]', icon: Clock3 }, INTERVIEW: { label: AdoptionStatusMap.INTERVIEW, class: 'border-[#5CD6C2] bg-[#DDF8F2] text-[#116B5E]', icon: MessageSquareText }, APPROVED: { label: AdoptionStatusMap.APPROVED, class: 'border-[#5CD6C2] bg-[#DDF8F2] text-[#116B5E]', icon: CheckCircle2 }, REJECTED: { label: AdoptionStatusMap.REJECTED, class: 'border-red-300 bg-red-50 text-red-700', icon: XCircle }, COMPLETED: { label: AdoptionStatusMap.COMPLETED, class: 'border-gray-300 bg-gray-100 text-gray-700', icon: ClipboardCheck }, CANCELLED: { label: AdoptionStatusMap.CANCELLED, class: 'border-gray-300 bg-gray-100 text-gray-600', icon: Ban }
}
const visiblePages = computed(() => { const start = Math.max(1, currentPage.value - 2); const end = Math.min(totalPages.value, currentPage.value + 2); return Array.from({ length: end - start + 1 }, (_, index) => start + index) })
const statusInfo = (status: AdoptionStatus) => statusConfig[status] || statusConfig.PENDING
const formatTime = (value?: string) => { if (!value) return '-'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit' }).format(date) }
const fetchAdoptions = async () => { const requestId = ++latestRequestId; loading.value = true; loadError.value = ''; try { const params: MyAdoptionQueryParams = { page: currentPage.value, size: pageSize, ...(selectedStatus.value ? { status: selectedStatus.value } : {}) }; const response = await adoptionApi.getMyAdoptions(params); if (requestId !== latestRequestId) return; adoptionList.value = response.items || []; totalPages.value = Math.max(Number(response.pages || 1), 1); total.value = Number(response.total || 0) } catch (error) { if (requestId !== latestRequestId) return; adoptionList.value = []; totalPages.value = 1; total.value = 0; loadError.value = error instanceof Error ? error.message : '领养申请暂时无法加载' } finally { if (requestId === latestRequestId) loading.value = false } }
const changePage = (page: number) => { if (page >= 1 && page <= totalPages.value && page !== currentPage.value) currentPage.value = page }
watch(selectedStatus, () => { if (currentPage.value === 1) void fetchAdoptions(); else currentPage.value = 1 })
watch(currentPage, () => void fetchAdoptions())
onMounted(() => void fetchAdoptions())
</script>

<template>
  <div class="min-h-full bg-gray-50 px-4 py-6 sm:px-6"><main class="mx-auto flex max-w-5xl flex-col gap-5"><header class="flex flex-col gap-4 border-b-2 border-black pb-5 sm:flex-row sm:items-end sm:justify-between"><div class="flex items-start gap-3"><Button variant="outline" size="icon" class="shrink-0 border-2 border-black bg-white hover:bg-[#5CD6C2]" aria-label="返回个人中心" @click="router.push('/userCenter')"><ArrowLeft class="size-4" /></Button><div><p class="text-sm font-bold text-gray-500">PERSONAL RECORDS</p><h1 class="mt-1 text-2xl font-black text-gray-950">我的领养申请</h1><p class="mt-2 text-sm text-gray-600">查看每一只猫咪的申请状态和审核反馈。</p></div></div><div class="border-2 border-black bg-white px-4 py-3 shadow-[3px_3px_0px_rgba(0,0,0,1)]"><p class="text-xs font-bold text-gray-500">申请总数</p><p class="text-lg font-black text-gray-950">{{ total }}</p></div></header><section class="border-2 border-black bg-white p-4 shadow-[4px_4px_0px_rgba(0,0,0,1)]"><div class="flex w-full overflow-x-auto border-2 border-black bg-gray-100 p-1 sm:w-fit"><button v-for="tab in statusTabs" :key="tab.value" type="button" class="min-h-9 shrink-0 px-4 text-sm font-bold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black" :class="selectedStatus === tab.value ? 'bg-[#5CD6C2] text-black shadow-[2px_2px_0px_rgba(0,0,0,1)]' : 'text-gray-600 hover:bg-white'" :aria-pressed="selectedStatus === tab.value" @click="selectedStatus = tab.value">{{ tab.label }}</button></div></section><section class="overflow-hidden border-2 border-black bg-white shadow-[5px_5px_0px_rgba(0,0,0,1)]"><div class="flex items-center justify-between border-b-2 border-black bg-[#F3F4F6] px-5 py-3"><h2 class="text-sm font-black">申请记录</h2><span class="text-xs font-bold text-gray-500">每页 {{ pageSize }} 条</span></div><div v-if="loading" class="py-16 text-center text-sm text-gray-500">正在加载领养申请...</div><div v-else-if="loadError" class="flex flex-col items-center gap-3 px-5 py-16 text-center text-sm text-red-700"><span>{{ loadError }}</span><Button variant="outline" size="sm" class="border-2 border-black" @click="fetchAdoptions">重新加载</Button></div><div v-else-if="adoptionList.length === 0" class="flex flex-col items-center gap-3 px-5 py-16 text-center text-gray-500"><HeartHandshake class="size-10 text-gray-300" /><p class="text-sm">当前筛选下没有领养申请</p><Button variant="outline" size="sm" class="border-2 border-black" @click="router.push('/cats')">查看可领养猫咪</Button></div><div v-else class="divide-y-2 divide-black"><article v-for="item in adoptionList" :key="item.id" class="flex flex-col gap-4 p-5 sm:flex-row sm:items-center"><img v-if="item.catAvatar" :src="item.catAvatar" :alt="item.catName" class="size-16 shrink-0 border-2 border-black object-cover" /><div v-else class="flex size-16 shrink-0 items-center justify-center border-2 border-black bg-gray-100"><HeartHandshake class="size-6 text-gray-500" /></div><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><button type="button" class="font-black text-gray-950 hover:text-[#116B5E]" @click="router.push(`/cat/${item.catId}`)">{{ item.catName }}</button><Badge variant="outline" class="gap-1 font-bold" :class="statusInfo(item.status).class"><component :is="statusInfo(item.status).icon" class="size-3.5" />{{ statusInfo(item.status).label }}</Badge></div><p class="mt-2 text-sm text-gray-600">提交于 {{ formatTime(item.createTime) }}</p><p v-if="item.reason" class="mt-3 border-l-4 p-3 text-sm leading-6" :class="item.status === 'REJECTED' ? 'border-red-400 bg-red-50 text-red-700' : 'border-[#5CD6C2] bg-[#DDF8F2] text-[#116B5E]'">{{ item.status === 'REJECTED' ? '审核说明：' : '处理说明：' }}{{ item.reason }}</p></div><Button variant="outline" size="sm" class="self-start border-2 border-black font-bold hover:bg-[#DDF8F2] sm:self-auto" @click="router.push(`/cat/${item.catId}`)">查看猫咪</Button></article></div><footer v-if="totalPages > 1" class="flex flex-col gap-3 border-t-2 border-black bg-[#F3F4F6] px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><span class="text-sm text-gray-600">第 <strong class="text-black">{{ currentPage }}</strong> / {{ totalPages }} 页</span><div class="flex flex-wrap items-center gap-2 self-end sm:self-auto"><Button variant="outline" size="sm" :disabled="currentPage <= 1" @click="changePage(currentPage - 1)">上一页</Button><Button v-for="page in visiblePages" :key="page" size="sm" :variant="page === currentPage ? 'default' : 'outline'" :class="page === currentPage ? 'border-2 border-black bg-[#5CD6C2] text-black hover:bg-[#5CD6C2]' : ''" @click="changePage(page)">{{ page }}</Button><Button variant="outline" size="sm" :disabled="currentPage >= totalPages" @click="changePage(currentPage + 1)">下一页</Button></div></footer></section></main></div>
</template>
